def orbit(r,c):
 return [(r,c),(c,r),(31-r,c),(r,31-c),(31-r,31-c),(31-c,31-r),(c,31-r),(31-c,r)]
conf=Counter(); ex=[]
for r in range(30):
 for c in range(30):
  vals=[a[x][y] for x,y in orbit(r,c) if x<30 and y<30 and a[x][y]!=6]
  if len(set(vals))>1:
   conf['conflict']+=1
   if len(ex)<15: ex.append(((r,c), vals))
conf,ex
